        // Plain buns
        for (int j = c0; j <= n; j++) {
            dp[j] = Math.max(dp[j], dp[j - c0] + d0);
        }

        // Stuffed buns
        for (int i = 0; i < m; i++) {
            int a = stuffings[i][0];
            int b = stuffings[i][1];
            int c = stuffings[i][2];
            int d = stuffings[i][3];

