public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int c0 = sc.nextInt();
        int d0 = sc.nextInt();

        int[][] items = new int[m+1][2];
        items[0][0] = c0;
        items[0][1] = d0;

        for (int i = 1; i <= m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            int d = sc.nextInt();
            int max = a / b;
            items[i][0] = c;
            items[i][1] = d;
            // Split into binary representation
            int k = 1;
            while (k <= max) {
                // Add item with k copies
                // We'll handle this by expanding the items array
                k <<= 1;
            }
        }

        // Create list of (cost, value) pairs
        List<int[]> list = new ArrayList<>();
        list.add(new int[]{c0, d0});
        for (int i = 1; i <= m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            int d = sc.nextInt();
            int max = a / b;
            int k = 1;
            while (k <= max) {
                list.add(new int[]{c * k, d * k});
                max -= k;
                k <<= 1;
            }
            if (max > 0) {
                list.add(new int[]{c * max, d * max});
            }
        }

        // 0-1 Knapsack
        int[] dp = new int[n+1];
        for (int[] item : list) {
            int cost = item[0];
            int val = item[1];
            for (int j = n; j >= cost; j--) {
                dp[j] = Math.max(dp[j], dp[j - cost] + val);
            }
        }

        System.out.println(dp[n]);
