            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
            d[i] = sc.nextInt();
        }

        int[] dp = new int[n+1];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int i = 0; i <= n; i++) {
            if (dp[i] != -1) {
                if (i + c0 <= n) {
                    dp[i + c0] = Math.max(dp[i + c0], dp[i] + d0);
                }
            }
        }

        for (int i = 1; i <= m; i++) {
            int maxBuns = a[i] / b[i];
            int[] newDp = Arrays.copyOf(dp, n+1);
            for (int j = 0; j <= n; j++) {
                if (dp[j] != -1) {
                    for (int k = 1; k <= maxBuns; k++) {
                        int cost = k * c[i];
                        if (j + cost > n) break;
                        newDp[j + cost] = Math.max(newDp[j + cost], dp[j] + k * d[i]);
                    }
                }
            }
            dp = newDp;
        }

        int ans = 0;
        for (int i = 0; i <= n; i++) {
            ans = Math.max(ans, dp[i]);
        }
