                for (int k = 1; k <= maxBuns && k * c[i - 1] <= j; k++) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - k * c[i - 1]] + k * d[i - 1]);
                }
            }
        }

        System.out.println(dp[m][n]);
    }
